using System; using System.Diagnostics; using System.ServiceProcess;
namespace PartnersInBiz { public sealed class RuntimeService:ServiceBase { Process child; public RuntimeService(){ServiceName="PartnersInBizRuntime";} protected override void OnStart(string[] a){child=Process.Start(new ProcessStartInfo(Environment.ExpandEnvironmentVariables(@"%ProgramFiles%\Partners in Biz\pib-runtime.exe"),"bridge"){UseShellExecute=false,CreateNoWindow=true});} protected override void OnStop(){if(child!=null&&!child.HasExited)child.Kill();} public static void Main(){ServiceBase.Run(new RuntimeService());} } }
